if (b.length == n) {
    return true;
}
if (n == 0) {
    deallocate(p, data, max_size, b);
    return true;
}
if (!b) {
    b = allocate(p, data, max_size, alignment, n);
    return b.length != 0;
}
const auto alignedLength = std::max(n, alignment - (n % alignment));
if (is_last_used_block(data, p, b)) {
    if (static_cast<char*>(b.ptr) + alignedLength <= data + max_size) {
        b.length = alignedLength;
        p = static_cast<char*>(b.ptr) + alignedLength;
        return true;
    }
    // out of memory
    return false;
}
if (b.length > n) {
    b.length = alignedLength;
    return true;
}
auto newBlock = allocate(p, data, max_size, alignment, alignedLength);
// we cannot deallocate the old block, because it is in between used ones,
// so we have to "leak" here.
if (newBlock) {
    std::memcpy(newBlock.ptr, b.ptr, std::min(b.length, n));
    b = newBlock;
    return true;
}
return false;

